          <Text style={<URL>atusText}>
            {status === 'uploading' ? 'Uploading...' : 'Processing...'}
          </Text>
        </View>
      )}
      {status === 'completed' && (
        <View style={<URL>sultContainer}>
          <MaterialIcons name="check-circle" size={24} color="#4CAF50" />
          <Text style={<URL>sultText}>{result}</Text>
          <TouchableOpacity
            style={styles.button}
            onPress={() => router.push('/(tabs)')}
          >
            <Text style={styles.buttonText}>Back to Home</Text>
          </TouchableOpacity>
        </View>
      )}
      {status === 'error' && (
        <View style={<URL>sultContainer}>
          <MaterialIcons name="error" size={24} color="#f44336" />
          <Text style={<URL>rorText}>{result}</Text>
          <TouchableOpacity
            style={styles.button}
            onPress={() => router.push('/(tabs)')}
          >
            <Text style={styles.buttonText}>Back to Home</Text>
          </TouchableOpacity>
