import * as Linking from 'expo-linking';
import { ClerkProvider } from "@clerk/clerk-expo";
import * as SecureStore from "expo-secure-store";
import Constants from 'expo-constants';
import { processSharedFile, cleanupSharedFile } from '@/utils/share-handler';

import { useColorScheme } from '@/hooks/useColorScheme';

// Prevent the splash screen from auto-hiding before asset loading is complete.
<REDACTED>();

const tokenCache = {
  async getToken(key: string) {
    try {
      return <URL>tItemAsync(key);
    } catch (err) {
      return null;
    }
  },
  async saveToken(key: string, value: string) {
    try {
      return <URL>tItemAsync(key, value);
    } catch (err) {
      return;
    }
  },
};

const CLERK_PUBLISHABLE_KEY = process.env.EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY;

export default function RootLayout() {
  const colorScheme = useColorScheme();
  const [loaded] = useFonts({
    SpaceMono: require('../assets/fonts/<URL>f'),
  });

  const publishableKey = Constants.expoConfig?.extra?.clerkPublishableKey as string;

  useEffect(() => {
    if (loaded) {
      SplashScreen.hideAsync();
    }
  }, [loaded]);

  useEffect(() => {
    // Handle initial URL when app is opened from share
    <URL>tInitialURL().then(handleIncomingURL);

    // Listen for URLs while app is running
    const subscription = <URL>dEventListener('url', ({ url }) => {
      handleIncomingURL(url);
    });

    return () => <URL>move();
  }, []);

  const handleIncomingURL = async (url: string | null) => {
    if (!url) return;

    try {
      const { path, queryParams } = <URL>rse(url);

      // Handle shared file URLs
      if (path === 'share') {
        if (queryParams?.uri) {
          const sharedFile = {
            uri: decodeURIComponent(queryParams.uri as string),
            mimeType: queryParams.type as string,
            name: <URL> as string,
          };

          const fileData = await processSharedFile(sharedFile);

          // Navigate to home screen with the file data
          router.push({
            pathname: '/(tabs)',
            params: { sharedFile: <URL>ringify(fileData) }
          });

          // Clean up temporary files after processing
          if (Platform.OS === 'android') {
            await cleanupSharedFile(sharedFile.uri);
          }
        } else if (queryParams?.text) {
          // Handle shared text
          const textData = {
            text: decodeURIComponent(queryParams.text as string),
            mimeType: 'text/plain',
            name: 'shared-text.txt'
          };

          router.push({
            pathname: '/(tabs)',
            params: { sharedFile: <URL>ringify(textData) }
          });
        }
      }
    } catch (error) {
      <URL>ror('Error handling shared content:', error);
    }
  };

  if (!loaded) {
    return null;
  }

  if (!CLERK_PUBLISHABLE_KEY) {
    throw new Error('Missing CLERK_PUBLISHABLE_KEY');
  }

  return (
    <ClerkProvider 
      publishableKey={CLERK_PUBLISHABLE_KEY}
      tokenCache={tokenCache}
    >
      <GestureHandlerRootView style={{ flex: 1 }}>
        <SafeAreaProvider>
          <ThemeProvider value={colorScheme === 'dark' ? DarkTheme : DefaultTheme}>
            <Stack
              screenOptions={{
                headerStyle: {
                  backgroundColor: '#f5f5f5',
                },
                headerTintColor: '#000',
                headerTitleStyle: {
                  fontWeight: '600',
                },
              }}
            >
              <<URL>reen name="(tabs)" options={{ headerShown: false }} />
              <<URL>reen name="(auth)" options={{ headerShown: false }} />
            </Stack>
            <StatusBar style={colorScheme === 'dark' ? 'light' : 'dark'} />
          </ThemeProvider>
        </SafeAreaProvider>
      </GestureHandlerRootView>
    </ClerkProvider>
  );
}

