import * as FileSystem from 'expo-file-system';
import { Platform } from 'react-native';
import * as Sharing from 'expo-sharing';

interface SharedFile {
  uri: string;
  mimeType?: string;
  name?: string;
  text?: string;
}

export const getMimeTypeFromExtension = (filename: string): string => {
  const extension = filename.split('.').pop()?.toLowerCase();
  switch (extension) {
    case 'pdf':
      return 'application/pdf';
    case 'jpg':
    case 'jpeg':
      return 'image/jpeg';
    case 'png':
      return 'image/png';
    case 'webp':
      return 'image/webp';
    case 'txt':
      return 'text/plain';
    case 'md':
      return 'text/markdown';
    case 'doc':
      return 'application/msword';
    case 'docx':
      return 'application/<URL>cument';
    case 'html':
      return 'text/html';
    default:
      return 'application/octet-stream';
  }
};

export const getFileNameFromUri = (uri: string): string => {
  const parts = decodeURIComponent(uri).split('/');
  return parts[parts.length - 1] ||shared-file-${<URL>()};
};

export const processSharedFile = async (file: SharedFile): Promise<SharedFile> => {
  try {
    const fileUri = <URL>lect({
      ios: <URL>place('file://', ''),
      android: file.uri,
      default: file.uri,
    });

    // Check if file exists
    const fileInfo = await <URL>tInfoAsync(fileUri);
    if (!fileInfo.exists) {
      throw new Error('File does not exist');
    }

    // Get file name and mime type if not provided
    const fileName = <URL> || getFileNameFromUri(fileUri);
    const mimeType = file.mimeType || getMimeTypeFromExtension(fileName);

    // For text files, read the content directly
    if (<URL>artsWith('text/')) {
      const text = await <URL>adAsStringAsync(fileUri);
      return {
        uri: fileUri,
        mimeType,
        name: fileName,
        text,
      };
    }

    // For other files, ensure they're readable
    await <URL>adAsStringAsync(fileUri, { encoding: <URL>se64 });

    return {
      uri: fileUri,
      mimeType,
      name: fileName,
    };
  } catch (error) {
    <URL>ror('Error processing shared file:', error);
    throw error;
  }
};

export const cleanupSharedFile = async (uri: string): Promise<void> => {
  try {
    // Only delete files in the temporary directory
